"""Generate Swift constants from the pinned conformance fixture."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
fixture = json.loads((root / "conformance/fixtures/constants.json").read_text())
output = ["// Copyright 2026 Mobilerun", "// SPDX-License-Identifier: Apache-2.0", "",
          "// Generated by tool/generate-constants.py; do not edit.", ""]
groups = {
    "control_msg_type": ("ControlMessageType", "Binary control message discriminators."),
    "amotion_event": ("MotionEvent", "Motion actions and mouse button masks."),
    "android_keys": ("AndroidKey", "Android keycodes, actions and modifier masks."),
}

def swift_name(key):
    words = key.lower().split("_")
    return words[0] + "".join(word.capitalize() for word in words[1:])

for key, (name, documentation) in groups.items():
    output += [f"/// {documentation}", f"public enum {name} {{"]
    for wire, value in fixture[key].items():
        output += [f"    /// Wire constant `{wire}`.",
                   f"    public static let {swift_name(wire)}: Int = {value}", ""]
    output += ["    /// All constants indexed by their protocol names.",
               "    static let values: [String: Int] = ["]
    output += [f'        "{wire}": {swift_name(wire)},' for wire in fixture[key]]
    output += ["    ]", "}", ""]
output += ["/// Layout-independent keyboard event codes mapped to Android keycodes.",
           "public enum KeyboardCode {", "    /// Lookup by keyboard event `code`.",
           "    public static let values: [String: Int] = ["]
output += [f'        {json.dumps(key)}: {value},' for key, value in fixture["code_map"].items()]
output += ["    ]", "}", ""]
(root / "Sources/MobilerunProtocol/Constants.swift").write_text("\n".join(output))

# USB HID Usage Tables, Keyboard/Keypad page 0x07 (UIKeyboardHIDUsage).
# Resolve through the pinned code_map instead of maintaining a second Android map.
hid = {4 + i: "Key" + chr(65 + i) for i in range(26)}
hid.update({30 + i: "Digit" + str((i + 1) % 10) for i in range(10)})
hid.update(dict(enumerate([
    "Enter", "Escape", "Backspace", "Tab", "Space", "Minus", "Equal", "BracketLeft",
    "BracketRight", "Backslash", None, "Semicolon", "Quote", "Backquote", "Comma", "Period", "Slash",
], 40)))
hid.update({58 + i: f"F{i + 1}" for i in range(12)})
hid.update(dict(enumerate([
    "Insert", "Home", "PageUp", "Delete", "End", "PageDown",
    "ArrowRight", "ArrowLeft", "ArrowDown", "ArrowUp",
], 73)))
hid.update(dict(enumerate(["NumpadDivide", "NumpadMultiply", "NumpadSubtract", "NumpadAdd",
                           "NumpadEnter"], 84)))
hid.update({89 + i: f"Numpad{i + 1}" for i in range(9)})
hid.update({98: "Numpad0", 99: "NumpadDecimal", 101: "ContextMenu", 103: "NumpadEqual",
            133: "NumpadComma"})
hid.update(dict(enumerate(["ControlLeft", "ShiftLeft", "AltLeft", "MetaLeft",
                           "ControlRight", "ShiftRight", "AltRight", "MetaRight"], 224)))
mapped = {usage: code for usage, code in hid.items() if code in fixture["code_map"]}
assert set(mapped.values()) == set(fixture["code_map"]), "unmapped fixture code"
header = ["// Copyright 2026 Mobilerun", "// SPDX-License-Identifier: Apache-2.0", "",
          "// Generated by tool/generate-constants.py; do not edit.", "",
          "/// USB HID Keyboard/Keypad usage to the pinned keyboard event code.",
          "package enum HIDCode {", "    package static let values: [Int: String] = ["]
header += [f'        {usage}: "{code}",' for usage, code in sorted(mapped.items())]
header += ["    ]", "}", ""]
(root / "Sources/MobilerunStreamCore/HIDCode.swift").write_text("\n".join(header))
